-- PowerOS baseline stage 09_hardening_fixes (fresh installs only). Source: migrations 20261207000000_customer_phone_uniqueness.sql .. 99999999999999_end.sql
-- Generated by tools/build_baseline.py; do NOT apply to a database that already has the migration history.

-- >>> 20261207000000_customer_phone_uniqueness.sql
-- Website-portal signups often arrive with no phone number, and sync_auth_to_customer()
-- stores the empty string (customers.phone is NOT NULL, so it cannot store NULL).
-- Migration 0042 made (org_id, phone) unique for every non-null value, which meant the
-- SECOND phone-less signup in an organisation failed with a duplicate-key error — the
-- auth insert itself was rejected. Keep the duplicate guard where it matters (real
-- phone numbers) and ignore the "unknown" placeholder value.
drop index if exists public.customers_phone_unique;

create unique index if not exists customers_phone_unique
  on public.customers (org_id, phone)
  where phone is not null and phone <> '';


-- >>> 20261208000000_patient_customer_id_columns.sql
-- The back-fill trigger from 20261125010000 writes sales.patient_customer_id and
-- lab_orders.patient_customer_id, but no migration in this repo ever creates those
-- columns: on a fresh database the BEFORE INSERT trigger therefore raises
--   record "new" has no field "patient_customer_id"
-- and every POS sale, website order and lab order is rejected. (In the environment
-- that migration was written against, the columns already existed.)
--
-- Create them when missing, copy the value the trigger would have derived, then hold
-- the NOT NULL invariant the original schema had. customer_id is NOT NULL on both
-- tables, so the back-fill always succeeds.
alter table public.sales
  add column if not exists patient_customer_id uuid references public.customers(id) on delete set null;

alter table public.lab_orders
  add column if not exists patient_customer_id uuid references public.customers(id) on delete set null;

update public.sales
   set patient_customer_id = customer_id
 where patient_customer_id is null and patient_customer_id is distinct from customer_id;

update public.lab_orders
   set patient_customer_id = customer_id
 where patient_customer_id is null and patient_customer_id is distinct from customer_id;

alter table public.sales alter column patient_customer_id set not null;

alter table public.lab_orders alter column patient_customer_id set not null;


-- >>> 20261209000000_cross_tenant_policy_fixes.sql
-- Cross-tenant read fixes (acceptance: "org A cannot read/write org B data").
--
-- 1. branches_active_read was created by 0020 for authenticated users with the
--    qualifier `is_active` and no organisation filter, so every signed-in user in
--    every tenant could read every other tenant's active branches. Staff already
--    have the org-scoped branch_read policy; this one now adds the same boundary
--    while keeping 0020's "active branches only" intent.
--    (20261122010000's automatic org-patching loop skipped it because it only
--    rewrites policies whose roles include anon/public.)
drop policy if exists branches_active_read on public.branches;

create policy branches_active_read on public.branches
  for select to authenticated
  using (is_active and org_id = public.current_org());

-- 2. site_pages.sp_anon was created after that same patch loop ran, so the public
--    website could render any tenant's pages. request_org() resolves the storefront
--    host for visitors and falls back to the signed-in user's own organisation.
drop policy if exists sp_anon on public.site_pages;

create policy sp_anon on public.site_pages
  for select to anon, authenticated
  using (is_active and org_id = public.request_org());


