-- Branch-private money data must stay branch-scoped (see 20261126000000:
-- "cashbook, expenses, day closing, purchases, credit notes, stock movements
-- stays branch-scoped"). The generic perm_read policies added by 20261122010000
-- only checked the organisation, so a branch manager with the finance permission
-- could read every branch's money data in the company — RLS ORs the permissive
-- policies, which made the branch-scoped *_rls_sel policies pointless.
--
-- Keep the original shape (org match + permission) and add the branch boundary for
-- signed-in users. Owners and admins pass can_access_branch() for every branch in
-- their organisation; the null-org path (public storefront context) is unchanged.
drop policy if exists perm_read on public.cashbook;

create policy perm_read on public.cashbook as permissive for select
  using ((current_org() is null or (has_permission('finance.view') and can_access_branch(branch_id)))
         and org_id = public.request_org());

drop policy if exists perm_read on public.day_closings;

create policy perm_read on public.day_closings as permissive for select
  using ((current_org() is null or (has_permission('finance.view') and can_access_branch(branch_id)))
         and org_id = public.request_org());

drop policy if exists perm_read on public.expenses;

create policy perm_read on public.expenses as permissive for select
  using ((current_org() is null or (has_permission('expenses.manage') and can_access_branch(branch_id)))
         and org_id = public.request_org());

drop policy if exists perm_read on public.purchase_invoices;

create policy perm_read on public.purchase_invoices as permissive for select
  using ((current_org() is null or (has_permission('purchases.manage') and can_access_branch(branch_id)))
         and org_id = public.request_org());


-- >>> 20261211000000_subscription_usage_refresh.sql
-- Usage snapshots (plan §7 limit keys, §6 /subscription/usage).
--
-- org_usage() computes live counts on demand; subscription_usage keeps a
-- per-period history so the company usage page and the platform admin view can
-- show "this month so far" instead of a number that silently changes.
-- The unique key (org_id, metric, period_start) makes refresh idempotent.

create or replace function public.refresh_subscription_usage(p_org uuid)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_period timestamptz := date_trunc('month', now());
  v_rows integer := 0;
  r record;
begin
  -- Callers may only refresh their own organisation. Service-role callers
  -- (cron, platform admin client) have no auth.uid() and pass this guard.
  if auth.uid() is not null
     and not exists (select 1 from public.profiles pr where pr.id = auth.uid() and pr.org_id = p_org)
     and not exists (select 1 from public.platform_users pu where pu.user_id = auth.uid() and pu.is_active) then
    raise exception 'refresh_subscription_usage: organisation mismatch';
  end if;

  for r in select metric, value from public.org_usage(p_org) loop
    insert into public.subscription_usage (org_id, metric, value, period_start, period_end, updated_at)
    values (p_org, r.metric, r.value, v_period, v_period + interval '1 month', now())
    on conflict (org_id, metric, period_start)
    do update set value = excluded.value, updated_at = now();
    v_rows := v_rows + 1;
  end loop;
  return v_rows;
end $$;

-- Scheduler variant: one pass over every organisation. Service-role only —
-- tenants must not be able to trigger company-wide work from a session.
create or replace function public.refresh_subscription_usage()
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_total integer := 0;
  o record;
begin
  -- The scheduler carries no tenant identity. Clear any residual JWT claims
  -- (set_config(..., true) is transaction-scoped, so a session can outlive the
  -- reset role that follows it) so the per-org guard sees a cron/service caller
  -- instead of a stale authenticated member of some other company.
  perform set_config('request.jwt.claims', '', true);
  perform set_config('request.jwt.claim.sub', '', true);
  for o in select id from public.organizations loop
    v_total := v_total + public.refresh_subscription_usage(o.id);
  end loop;
  return v_total;
end $$;

revoke execute on function public.refresh_subscription_usage() from public, anon, authenticated;

grant execute on function public.refresh_subscription_usage() to service_role;

-- The per-org variant is self-guarding (own org or platform admin only).
revoke execute on function public.refresh_subscription_usage(uuid) from public, anon;

grant execute on function public.refresh_subscription_usage(uuid) to authenticated, service_role;

-- Daily snapshot, installed only when pg_cron is present (same note as
-- 20261206000000_subscription_lifecycle.sql). The `/subscription/usage` page
-- refreshes the caller's own row on demand, so local/dev without pg_cron still
-- shows fresh numbers.
do $do$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    if exists (select 1 from cron.job where jobname = 'subscription-usage') then
      perform cron.unschedule('subscription-usage');
    end if;
    perform cron.schedule('subscription-usage', '5 0 * * *',
                          $$select public.refresh_subscription_usage()$$);
  end if;
end $do$;


-- >>> 20261212000000_role_model_expansion.sql
-- Role model expansion (plan §5: "role-based employee workspaces").
-- The app already ships ten employee roles (validators, /settings/roles, the
-- per-role widgets on /) but the database still enforced the original four
-- keys, so an owner assigning "accountant" would fail a CHECK and (worse) the
-- middleware route rules would bounce any non-standard key into a redirect
-- loop. This widens the allow-lists additively: every existing key stays
-- valid and owner/admin/branch_manager/staff behaviour is unchanged.
--
-- Specialised roles are staff-tier for routing (branch-bound, no admin
-- routes); what distinguishes them is their default permission grants below.

-- ── 1. profiles may carry any app role key ───────────────────────────────────
alter table profiles drop constraint if exists profiles_role_key_chk;

alter table profiles add constraint profiles_role_key_chk check (role_key in (
  'owner', 'admin', 'branch_manager', 'staff',
  'optometrist', 'sales_executive', 'cashier',
  'inventory_manager', 'lab_technician', 'accountant', 'receptionist'));

-- ── 2. Per-org grants exist for every non-admin role ─────────────────────────
-- owner/admin bypass has_perm() outright, so they never need rows here.
alter table role_permissions drop constraint if exists role_permissions_role_key_check;

alter table role_permissions add constraint role_permissions_role_key_check check (role_key in (
  'branch_manager', 'staff',
  'optometrist', 'sales_executive', 'cashier',
  'inventory_manager', 'lab_technician', 'accountant', 'receptionist'));

-- ── 3. Invitations can carry any non-admin role ──────────────────────────────
alter table staff_invitations drop constraint if exists staff_invitations_role_key_check;

alter table staff_invitations add constraint staff_invitations_role_key_check check (role_key in (
  'admin', 'branch_manager', 'staff',
  'optometrist', 'sales_executive', 'cashier',
  'inventory_manager', 'lab_technician', 'accountant', 'receptionist'));

-- ── 4. Default grants per specialised role ───────────────────────────────────
-- permission_catalog drives seed_org_permissions() for new organisations.
-- crm_manage and discount_override stay branch_manager-only on purpose:
-- CRM routes are manager-tier and discount override is a sensitive right.
update permission_catalog set default_roles = array['branch_manager', 'accountant', 'cashier']
  where key = 'finance_view';

update permission_catalog set default_roles = array['branch_manager', 'accountant']
  where key in ('expenses', 'day_closing', 'reports_view');

update permission_catalog set default_roles = array['branch_manager', 'inventory_manager']
  where key in ('catalogue_edit', 'stock_adjust', 'stock_audit', 'transfers_approve', 'purchases_manage');

update permission_catalog set default_roles = array['branch_manager', 'sales_executive']
  where key = 'web_orders';

update permission_catalog set default_roles = array['branch_manager', 'cashier']
  where key = 'credit_notes.issue';

-- ── 5. Seeding accepts the new keys, then backfills existing organisations ──
create or replace function public.seed_org_permissions(p_org uuid) returns void
language sql security definer set search_path to 'public' as $function$
  insert into role_permissions (org_id, role_key, permission)
  select p_org, r, c.key from permission_catalog c, unnest(c.default_roles) r
  where r in ('branch_manager', 'staff',
              'optometrist', 'sales_executive', 'cashier',
              'inventory_manager', 'lab_technician', 'accountant', 'receptionist')
  on conflict do nothing $function$;

select public.seed_org_permissions(id) from organizations;

-- ── 6. Owners/admins may grant any non-admin role ────────────────────────────
create or replace function public.set_role_permission(p_role text, p_permission text, p_allowed boolean)
returns void language plpgsql security definer set search_path to 'public' as $function$
begin
  if not public.is_admin() then raise exception 'Only owners and admins can change permissions' using errcode='42501'; end if;
  if p_role not in ('branch_manager', 'staff',
                    'optometrist', 'sales_executive', 'cashier',
                    'inventory_manager', 'lab_technician', 'accountant', 'receptionist')
     or p_allowed is null or not exists(select 1 from public.permission_catalog where key=p_permission) then
    raise exception 'Invalid role permission';
  end if;
  insert into public.role_permissions(org_id, role_key, permission, allowed)
  values(public.current_org(), p_role, p_permission, p_allowed)
  on conflict(org_id, role_key, permission) do update
    set allowed = excluded.allowed, updated_by = auth.uid(), updated_at = now();
end $function$;

-- ── 7. Staff lifecycle RPCs accept the full role set ─────────────────────────
create or replace function public.admin_update_staff(p_id uuid, p_role text default null, p_branch uuid default null,
    p_set_branch boolean default false, p_deactivated boolean default null) returns void
language plpgsql security definer set search_path to 'public' as $$
declare c profiles; t profiles; v_role text; v_deact boolean;
begin
  select * into c from profiles where id = auth.uid() and is_approved and not deactivated;
  if not found or c.role_key not in ('owner', 'admin') then raise exception 'Only owners and admins can manage staff' using errcode = '42501'; end if;
  select * into t from profiles where id = p_id and org_id = c.org_id for update;
  if not found then raise exception 'Staff member not found'; end if;
  if t.id = c.id and (p_role is not null or p_deactivated is true) then raise exception 'You cannot change your own role or deactivate yourself'; end if;
  if c.role_key <> 'owner' and (t.role_key in ('owner', 'admin') or p_role in ('owner', 'admin')) then
    raise exception 'Only an owner can manage or grant admin/owner access' using errcode = '42501'; end if;
  if p_role is not null and p_role not in ('owner', 'admin', 'branch_manager', 'staff',
      'optometrist', 'sales_executive', 'cashier',
      'inventory_manager', 'lab_technician', 'accountant', 'receptionist') then
    raise exception 'Invalid role'; end if;
  v_role := coalesce(p_role, t.role_key); v_deact := coalesce(p_deactivated, t.deactivated);
  if t.role_key = 'owner' and (v_role <> 'owner' or v_deact) and
     not exists (select 1 from profiles o where o.org_id = t.org_id and o.role_key = 'owner' and o.is_approved and not o.deactivated and o.id <> t.id) then
    raise exception 'An organisation must keep at least one active owner'; end if;
  if p_set_branch and p_branch is not null and not exists (select 1 from branches where id = p_branch and org_id = c.org_id) then
    raise exception 'Branch not in your organisation'; end if;
  update profiles set role_key = v_role, deactivated = v_deact, is_approved = not v_deact,
         branch_id = case when p_set_branch then p_branch else branch_id end,
         branch_reviewed = case when p_set_branch then true else branch_reviewed end where id = t.id;
  if v_deact then update staff_assignments set revoked_at = now(), revoked_by = c.id where profile_id = t.id and revoked_at is null; end if;
end $$;

create or replace function public.invite_staff(p_email text, p_role text, p_branch uuid default null) returns uuid
language plpgsql security definer set search_path to 'public' as $$
declare c profiles; v_id uuid; v_email text := lower(trim(p_email));
begin
  select * into c from profiles where id = auth.uid() and is_approved and not deactivated;
  if not found or c.role_key not in ('owner', 'admin') then raise exception 'Only owners and admins can invite staff' using errcode = '42501'; end if;
  if v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'Enter a valid email'; end if;
  if p_role not in ('admin', 'branch_manager', 'staff',
                    'optometrist', 'sales_executive', 'cashier',
                    'inventory_manager', 'lab_technician', 'accountant', 'receptionist') then
    raise exception 'Invalid role'; end if;
  if c.role_key <> 'owner' and p_role = 'admin' then raise exception 'Only an owner can invite admins' using errcode = '42501'; end if;
  -- Every non-admin role is branch-bound: the invite must say where they work.
  if p_role not in ('owner', 'admin') and p_branch is null then raise exception 'Choose a branch'; end if;
  if p_branch is not null and not exists (select 1 from branches where id = p_branch and org_id = c.org_id and is_active) then raise exception 'Branch not in your organisation'; end if;
  update staff_invitations set revoked_at = now() where org_id = c.org_id and lower(email) = v_email and accepted_at is null and revoked_at is null;
  insert into staff_invitations (org_id, email, role_key, branch_id) values (c.org_id, v_email, p_role, p_branch) returning id into v_id;
  return v_id;
end $$;


-- >>> 20261213000000_cancelled_access_until_period_end.sql
-- Cancelled is not a lockout (plan §8 + lifecycle step 4).
--
-- The plan's state table spells out write blocking for 'expired' and
-- 'suspended' but not for 'cancelled', and the lifecycle job has always
-- treated cancelled as a state that runs until current_period_end ("Cancelled
-- at the end of the period it already paid for") before flipping the row to
-- 'expired'. The entitlement function disagreed: it blocked writes the moment
-- a company cancelled, which locked staff out mid-day and made the later
-- cancelled -> expired transition pointless bookkeeping.
--
-- New rule, in one place (resolve_entitlements is the single source both the
-- app gate and any future DB consumer read):
--   expired / suspended      -> writes blocked from the moment they are set
--   cancelled, period still running -> writes allowed (auto_renew is off)
--   cancelled, period over (or no period) -> writes blocked until renewal
-- Reads, billing, export and support stay open for all of them either way.

create or replace function public.resolve_entitlements(p_org uuid)
returns jsonb language plpgsql stable security definer set search_path=public as $$
declare
  v_sub record;
  v_plan record;
  v_status text;
  v_features jsonb := '{}'::jsonb;
  v_limits jsonb := '{}'::jsonb;
begin
  select * into v_sub from public.org_subscriptions
    where org_id = p_org order by created_at desc limit 1;

  if v_sub is null then
    -- No subscription: minimal read-only entitlements
    return jsonb_build_object('status','none','features',jsonb_build_object(),'limits',jsonb_build_object('branches',1,'employees',3,'customers',100,'storage_mb',100));
  end if;

  v_status := v_sub.status;
  -- grace window handling
  if v_status = 'past_due' and v_sub.grace_ends_at is not null and v_sub.grace_ends_at > now() then
    v_status := 'grace';
  end if;

  select * into v_plan from public.billing_plans where id = v_sub.plan_id;

  if v_plan is null then
    return jsonb_build_object('status', v_status, 'features', jsonb_build_object(), 'limits', jsonb_build_object());
  end if;

  v_features := coalesce(v_plan.features, '{}'::jsonb);
  v_limits := jsonb_build_object(
    'branches', v_plan.max_branches,
    'employees', v_plan.max_employees,
    'customers', v_plan.max_customers,
    'storage_mb', v_plan.storage_mb
  );

  -- Expired/suspended block writes immediately. Cancelled only blocks once the
  -- period it already paid for has ended (the daily lifecycle job then moves
  -- the row to 'expired', so the blocked state never dangles on 'cancelled').
  if v_status in ('expired','suspended')
     or (v_status = 'cancelled'
         and (v_sub.current_period_end is null or v_sub.current_period_end <= now())) then
    v_features := v_features || jsonb_build_object('_writes_blocked', true);
  end if;

  return jsonb_build_object(
    'status', v_status,
    'plan_code', v_plan.code,
    'plan_name', v_plan.name,
    'trial_ends_at', v_sub.trial_ends_at,
    'grace_ends_at', v_sub.grace_ends_at,
    'current_period_end', v_sub.current_period_end,
    'features', v_features,
    'limits', v_limits
  );
end $$;

grant execute on function public.resolve_entitlements(uuid) to authenticated, service_role;


-- >>> 20261214000000_platform_break_glass.sql
-- Platform break-glass (plan §6/§10 + acceptance criterion 5).
--
-- Platform admins run companies through billing/subscription metadata only;
-- customer records are company-private. When support genuinely needs to look at
-- a company's private data, access must be EXPLICIT (a typed reason of at least
-- 10 characters), SCOPED (one platform user × one company), SHORT-LIVED
-- (30 minutes, bounded by the database itself) and AUDITED (platform_audit_logs
-- on grant, view and revoke — the app writes those alongside this row).
--
-- This table is the grant. RLS is enabled with NO policies and privileges are
-- revoked from anon/authenticated, so tenants can neither read nor mint grants:
-- only the service-role client reaches it, and only from platform routes after
-- requirePlatform() has succeeded.

create table if not exists public.break_glass_grants (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references public.organizations(id) on delete cascade,
  platform_user_id uuid not null,              -- auth user id of the platform admin
  reason text not null check (length(trim(reason)) >= 10),
  granted_at timestamptz not null default now(),
  expires_at timestamptz not null default (now() + interval '30 minutes'),
  viewed_at timestamptz,
  revoked_at timestamptz,
  constraint break_glass_window check (expires_at > granted_at)
);

create index if not exists break_glass_grants_org_idx
  on public.break_glass_grants (org_id, granted_at desc);

alter table public.break_glass_grants enable row level security;

-- Deliberately zero policies: deny-by-default for every tenant role.
revoke all on table public.break_glass_grants from anon, authenticated;


-- >>> 20261215000000_grandfather_backfill_function.sql
-- Grandfathering backfill as a first-class, testable function
-- (plan §11 criterion 9: "migrations apply cleanly to an existing DB;
-- backfill grandfathered plans").
--
-- 20261201000000 step 9 ran this exact statement inline during the original
-- rollout. Extracting it here makes it re-runnable (idempotent — only
-- organisations with NO subscription row at all are touched) so a restored or
-- imported database can reach the same invariant, and supabase/tests/
-- saas_platform.sql can assert the behaviour for real instead of trusting the
-- statement exists.
--
-- Scope: an organisation with no subscription row resolves to status 'none'
-- (writes blocked, reads only). Grandfathering it onto the hidden, free
-- 'legacy' plan is exactly what the plan promises for pre-subscription data.
-- Any organisation that already has a subscription row — trialing, expired,
-- cancelled, whatever — is never touched; its own history is preserved.
--
-- EXECUTE is revoked from tenant roles: only the migration superuser and the
-- service role can run it (org_subscriptions writes are service-side anyway).

create or replace function public.backfill_grandfather_subscriptions()
returns integer language sql security definer set search_path = public as $$
  with inserted as (
    insert into public.org_subscriptions (org_id, plan_id, status, current_period_start, current_period_end)
    select o.id, (select id from public.billing_plans where code = 'legacy'), 'active',
           now(), now() + interval '10 years'
    from public.organizations o
    where not exists (select 1 from public.org_subscriptions s where s.org_id = o.id)
    returning 1
  )
  select count(*) from inserted;
$$;

revoke execute on function public.backfill_grandfather_subscriptions() from public, anon, authenticated;

grant execute on function public.backfill_grandfather_subscriptions() to service_role;

-- Re-apply the invariant on every migration run (no-op on a healthy database).
select public.backfill_grandfather_subscriptions();


-- >>> 20261216000000_security_audit_fixes.sql
-- Phase 7 — RLS policy audit: findings and fixes (plan §4 bullet 5, §10 risk 1).
-- Audit method + manual checklist: docs/SECURITY_PENTEST_CHECKLIST.md.
-- Regression proof: supabase/tests/rls_audit.sql.
--
-- Finding 1 — views bypassed RLS.
-- customer_orders, customer_loyalty_balance, itc_summary, open_po_value and
-- product_review_summary were created without security_invoker, so they ran
-- with the owner's (postgres) rights and ignored the RLS of their base
-- tables. Any authenticated tenant could read every organisation's rows
-- straight from the PostgREST endpoint. Fix: run them with the caller's
-- rights; the underlying tenant policies then scope each caller to its own
-- organisation. The service role (BYPASSRLS) still sees every row, and the
-- two public_* views are deliberately untouched — they filter on
-- request_org() by design and only expose website-public rows.
alter view public.customer_orders set (security_invoker = true);

alter view public.customer_loyalty_balance set (security_invoker = true);

alter view public.itc_summary set (security_invoker = true);

alter view public.open_po_value set (security_invoker = true);

alter view public.product_review_summary set (security_invoker = true);

-- Finding 2 — cross-org RPCs.
-- resolve_entitlements(org), org_usage(org) and seed_org_permissions(org)
-- were executable by any authenticated user (and, through the default PUBLIC
-- grant, by anon) with an arbitrary org argument: a cross-org read of
-- subscription state and headcounts, plus a cross-org permission re-seed.
-- The app only ever needs "my own organisation", so the parameter is taken
-- away entirely for tenant roles:
--   * revoke the raw functions from tenant roles (service_role, triggers,
--     definer functions and migrations keep EXECUTE — all non-tenant
--     callers),
--   * expose no-arg wrappers that resolve the caller's org server-side via
--     current_org() (profiles lookup by verified auth.uid(), so a tenant can
--     only ever resolve itself).
revoke execute on function public.resolve_entitlements(uuid) from public, anon, authenticated;

revoke execute on function public.org_usage(uuid) from public, anon, authenticated;

revoke execute on function public.seed_org_permissions(uuid) from public, anon, authenticated;

grant execute on function public.resolve_entitlements(uuid) to service_role;

grant execute on function public.org_usage(uuid) to service_role;

grant execute on function public.seed_org_permissions(uuid) to service_role;

create or replace function public.my_entitlements()
returns jsonb language sql stable security definer set search_path = public as $$
  select case when public.current_org() is null then null
              else public.resolve_entitlements(public.current_org()) end;
$$;

grant execute on function public.my_entitlements() to authenticated;

create or replace function public.my_org_usage()
returns table(metric text, value bigint)
language sql stable security definer set search_path = public as $$
  select u.* from public.org_usage(public.current_org()) u;
$$;

grant execute on function public.my_org_usage() to authenticated;

-- Finding 3 — unscoped review insert.
-- product_reviews.reviews_insert had WITH CHECK (true) while every read
-- policy on the same table scopes with request_org(): an anon caller could
-- insert review rows (pending, but still writes) into any organisation if it
-- knew a product id — and product ids are public via public_catalog. Tighten
-- the insert to the same resolution the read policies use.
drop policy if exists reviews_insert on product_reviews;

create policy reviews_insert on product_reviews
  for insert to anon with check (org_id = request_org());


-- >>> 20261217000000_fix_schema_drift.sql
-- Forward security fixes for tenant-facing public policies.
-- This migration is intentionally separate from older migrations that may
-- already be marked applied in hosted Supabase projects.

-- Site pages are public only within the storefront tenant resolved from host.
drop policy if exists sp_anon on public.site_pages;

create policy sp_anon on public.site_pages
  for select to anon, authenticated
  using (is_active and org_id = public.request_org());

-- A public review must belong to the current storefront and an active product
-- in that same organisation. Do not trust a browser-supplied customer_id or
-- verified_purchase flag; verified purchase attribution requires a separate
-- server-side order check and is deliberately disabled until then.
drop policy if exists reviews_insert on public.product_reviews;

create policy reviews_insert on public.product_reviews
  for insert to anon, authenticated
  with check (
    org_id = public.request_org()
    and customer_id is null
    and verified_purchase = false
    and status = 'pending'
    and exists (
      select 1
      from public.products p
      where p.id = product_id
        and p.org_id = public.request_org()
        and p.status = 'active'
        and p.visible_on_website = true
    )
  );

-- Tenant IDs and names are not a public directory. Storefront code resolves
-- the active organisation through the host-bound org_for_host RPC instead.
drop policy if exists org_anon on public.organizations;


