  if not exists (select 1 from pg_constraint where conname = 'customer_notification_preferences_pkey' and conrelid = 'customer_notification_preferences'::regclass) then
    ALTER TABLE ONLY "public"."customer_notification_preferences" ADD CONSTRAINT "customer_notification_preferences_pkey" PRIMARY KEY ("customer_id");
  end if;
end $$;

do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'customer_notifications_customer_id_source_key_key' and conrelid = 'customer_notifications'::regclass) then
    ALTER TABLE ONLY "public"."customer_notifications" ADD CONSTRAINT "customer_notifications_customer_id_source_key_key" UNIQUE ("customer_id", "source_key");
