  if not exists (select 1 from pg_constraint where conname = 'palre_recommendation_runs_org_id_prescription_id_fkey' and conrelid = 'palre_recommendation_runs'::regclass) then
    ALTER TABLE ONLY "public"."palre_recommendation_runs" ADD CONSTRAINT "palre_recommendation_runs_org_id_prescription_id_fkey" FOREIGN KEY ("org_id", "prescription_id") REFERENCES "public"."prescriptions"("org_id", "id");
  end if;
end $$;

do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'staff_invitations_accepted_user_id_fkey' and conrelid = 'staff_invitations'::regclass) then
    ALTER TABLE ONLY "public"."staff_invitations" ADD CONSTRAINT "staff_invitations_accepted_user_id_fkey" FOREIGN KEY ("accepted_user_id") REFERENCES "public"."profiles"("id");
  end if;
end $$;

