-- >>> 20261219000000_site_pages_defaults.sql
-- Seed the starter website pages for EVERY organisation (new ones too). Before this, only organisations that existed when
-- the pages migration ran had rows, so /about, /clinic, /lab, /faq … returned 404 for new companies.
-- Also: system pages cannot be deleted (hide them instead), slugs are validated, and custom pages are supported.
alter table site_pages add column if not exists is_system boolean not null default false;

alter table site_pages drop constraint if exists site_pages_slug_chk;

alter table site_pages add constraint site_pages_slug_chk check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$') not valid;

create or replace function public.seed_site_pages(p_org uuid) returns void
language plpgsql security definer set search_path = public as $fn$
begin
insert into site_pages (org_id, slug, kind, title, subtitle, body, show_in_nav, display_order)
select o.id, v.slug, v.kind, v.title, v.subtitle, v.body::jsonb, v.nav, v.ord from (select p_org as id) o, (values
 ('guide-eyeglasses','guide','Frame Size Guide','Find the frame that fits your face','{"sections":[{"heading":"Read your frame size","body":"Three numbers are printed inside the temple arm, e.g. 52-18-140: lens width, bridge width and temple length (mm)."},{"heading":"Measure your face","body":"Hold a ruler across your cheekbones. Under 125mm is narrow, 125–135mm medium, above 135mm wide."}],"table":{"headers":["Fit","Lens width","Bridge","Temple"],"rows":[["Narrow","44–48","16–18","130–135"],["Medium","49–53","17–19","135–140"],["Wide","54–58","18–20","140–150"]]}}',false,10),
 ('guide-sunglasses','guide','Sunglasses Guide','Protection and style, explained','{"sections":[{"heading":"UV400 protection","body":"Look for UV400 so both UVA and UVB rays are blocked."},{"heading":"Polarised lenses","body":"Cut glare from roads and water, ideal for driving and travel."},{"heading":"Lens colour","body":"Grey keeps true colour, brown boosts contrast, green is balanced for everyday wear."}]}',false,11),
 ('guide-contact-lenses','guide','Contact Lens Guide','Choose the right lenses','{"sections":[{"heading":"Daily vs monthly","body":"Dailies are thrown away each night for maximum hygiene. Monthlies are economical with a care routine."},{"heading":"Astigmatism","body":"Toric lenses correct astigmatism and need a fitting."},{"heading":"Prescription needed","body":"Contact lens power differs from spectacle power. Book a fitting if you are new to lenses."}]}',false,12),
 ('guide-computer-glasses','guide','Computer Glasses Guide','Comfort for long screen hours','{"sections":[{"heading":"Blue-light filter","body":"Reduces high-energy blue light from screens, helping with eye strain and sleep."},{"heading":"20-20-20 rule","body":"Every 20 minutes look at something 20 feet away for 20 seconds."},{"heading":"Anti-reflective coating","body":"Cuts screen glare so text looks crisper."}]}',false,13),
 ('guide-lenses','guide','Lens & Coating Guide','Index, designs and coatings','{"sections":[{"heading":"Lens index","body":"Higher index means thinner, lighter lenses. Choose 1.67 or 1.74 for strong powers."},{"heading":"Designs","body":"Single vision for one distance, bifocal or progressive for near and far."},{"heading":"Coatings","body":"Anti-glare, scratch-resistant, hydrophobic and blue-cut coatings extend life and comfort."}]}',false,14),
 ('about','page','About Us','Caring for your eyes since 1998','{"stats":[{"value":"25+","label":"Years of trust"},{"value":"2","label":"Stores"},{"value":"100%","label":"Genuine brands"}],"sections":[{"heading":"Our story","body":"Power Eyes Opticals began in Mogappair, Chennai, with one promise: honest, expert eye care for every family."},{"heading":"What we stand for","body":"Authentic brands, transparent pricing, free lifetime adjustments and complete prescription privacy."}]}',true,1),
 ('clinic','page','Our Eye Clinic','Clinic-grade eye testing in-store','{"sections":[{"heading":"Comprehensive eye test","body":"Auto-refraction, subjective refinement, binocular vision checks and eye-health screening by qualified optometrists."},{"heading":"Contact lens fitting","body":"Trial lenses, handling training and follow-ups."},{"heading":"Children''s eye care","body":"Gentle, child-friendly testing and myopia guidance."}]}',true,2),
 ('lab','page','Our Lab','Precision lenses, made in-house','{"sections":[{"heading":"Precision edging","body":"Digital centration and computer-controlled edging for accurate fitting."},{"heading":"Quality checks","body":"Every pair passes power, axis, coating and cosmetic inspection before delivery."},{"heading":"Fast turnaround","body":"Most single-vision orders are ready within 24–48 hours."}]}',true,3),
 ('eye-consultation','config','Eye Consultation','Book a professional eye test','{"price":"","duration":"30 min","intro":"Professional eye care at our stores.","types":["Comprehensive Eye Test","Contact Lens Fitting","Follow Up","Consultation"],"times":["09:30 AM","10:00 AM","10:30 AM","11:00 AM","02:00 PM","02:30 PM","03:00 PM","04:00 PM","04:30 PM"],"cta":"Confirm via WhatsApp","note":"We confirm within 30 minutes.","closed_weekdays":[]}',false,4)
) as v(slug,kind,title,subtitle,body,nav,ord)
on conflict (org_id, slug) do nothing;

-- Listing-page hero text (title/subtitle/hero_image) editable per category.
insert into site_pages (org_id, slug, kind, title, subtitle, body, display_order)
select o.id, v.slug, 'config', v.title, v.subtitle, '{}'::jsonb, v.ord from (select p_org as id) o, (values
 ('hero-eyeglasses','Eyeglasses','Prescription frames for every face and lifestyle',20),
 ('hero-sunglasses','Sunglasses','Style meets protection – regular & prescription sunglasses',21),
 ('hero-contact-lenses','Contact Lenses','Daily, monthly and coloured lenses from leading brands',22),
 ('hero-computer-glasses','Computer & Blue Light Glasses','Protect your eyes from digital strain',23),
 ('hero-lenses','Lens & Coatings','Choose the right index, design and coating',24)
) as v(slug,title,subtitle,ord) on conflict (org_id, slug) do nothing;

-- Policy / FAQ pages (seeded from the previous hard-coded content; edit in Website Studio).
insert into site_pages (org_id, slug, kind, title, subtitle, body, show_in_nav, display_order)
select o.id, v.slug, 'page', v.title, v.subtitle, v.body::jsonb, false, v.ord from (select p_org as id) o, (values
  ('privacy', 'Privacy Policy', 'How we collect, use and protect your data', $j${"sections":[{"heading":"Information We Collect","body":"When you use the Power Eyes Opticals website or visit our stores, we collect information you provide directly: your name, phone number and email address when you create an account or place an order; your eye prescription (SPH, CYL, Axis, ADD, PD) when you upload a prescription or book a lens order; your delivery address when you choose home delivery; your payment method details, which are processed securely by Razorpay and never stored on our servers; and any messages you send us via our contact form or WhatsApp.\n\nWe also collect information automatically: pages visited, time spent on each page, browser type and device type through standard web analytics."},{"heading":"How We Use Your Information","body":"We use your information to process and fulfil your orders, send order confirmations and status updates via WhatsApp and email, prepare your prescription lenses accurately and safely, communicate with you about appointments you book, send you information about offers and promotions if you have opted in, improve our website and services, and comply with legal obligations.\n\nYour prescription information is used only for fulfilling your lens order. It is shared with our lens laboratory partners only to the extent necessary to manufacture your lenses."},{"heading":"Eye Prescription Data","body":"Your eye prescription is sensitive health information. We treat it with the highest level of care. Your prescription is stored securely in our database and is accessible only to you through your Vision ID and to our trained optometrists and dispensing staff.\n\nWe do not sell, rent or share your prescription data with any third party for marketing purposes. Our lab partners receive only the prescription values necessary to manufacture your lenses and are contractually required to delete that data after production."},{"heading":"Sharing Your Information","body":"We share your information only in these limited circumstances: with Razorpay to process your payment; with our lens laboratory to manufacture your prescription lenses; with courier partners to deliver your order; with legal or regulatory authorities if required by law.\n\nWe do not sell your personal information to any third party."},{"heading":"Data Security","body":"We use industry-standard security measures including HTTPS encryption for all data transmission, secure database hosting via Supabase on AWS infrastructure, password hashing and secure session management, and regular security reviews.\n\nPayment card details are never stored on our servers — all payments are handled directly by Razorpay, which is PCI-DSS Level 1 certified."},{"heading":"Cookies","body":"Our website uses cookies for essential functions (keeping you logged in, remembering your cart) and analytics (understanding how visitors use our site via anonymous statistics). You can disable non-essential cookies in your browser settings without affecting core site functionality."},{"heading":"Your Rights","body":"You have the right to access the personal information we hold about you, correct any inaccurate information, request deletion of your account and associated data, opt out of marketing communications at any time, and download your prescription data.\n\nTo exercise any of these rights, email us at powereyes.chennai@gmail.com or contact us via WhatsApp on 9840496404."},{"heading":"Changes to This Policy","body":"We may update this privacy policy from time to time. We will notify registered customers of significant changes via email or WhatsApp. Continued use of our website after a change constitutes acceptance of the updated policy."}]}$j$, 30),
  ('terms', 'Terms of Service', 'The terms that apply when you use our website and stores', $j${"sections":[{"heading":"Acceptance of Terms","body":"By using the Power Eyes Opticals website (powereyes.in) or purchasing from our stores, you agree to these Terms of Service. If you do not agree, please do not use our website."},{"heading":"Products and Pricing","body":"All product prices are displayed in Indian Rupees (₹) and are inclusive of GST unless stated otherwise. Prices are subject to change without notice. In the event of a pricing error, we reserve the right to cancel the order and refund the amount paid. Product images are for illustration — actual colour and dimensions may vary slightly."},{"heading":"Prescription Accuracy","body":"You are responsible for providing an accurate, current prescription. Power Eyes Opticals will manufacture lenses based on the prescription you provide. We are not liable for vision problems resulting from an inaccurate prescription supplied by the customer. Prescriptions must be issued by a registered optometrist or ophthalmologist and must be valid (within 2 years for glasses, 1 year for contact lenses)."},{"heading":"Orders and Payment","body":"Placing an order constitutes an offer to purchase. We reserve the right to accept or decline any order. Full payment is required at the time of online order placement. For high-value or custom orders, we may require an advance payment confirmation before beginning production."},{"heading":"Delivery","body":"Delivery timelines are estimates, not guarantees. Power Eyes Opticals is not responsible for delays caused by courier partners, natural events or circumstances beyond our control. Risk of damage or loss passes to the customer upon delivery confirmation."},{"heading":"Returns and Exchanges","body":"Unworn frames may be returned within 7 days of purchase with original bill and packaging. Prescription lenses are custom-made and cannot be returned unless there is a manufacturing defect. If the lenses do not match the prescription you provided, we will remake them within 30 days at no charge. Hygiene products (contact lenses, nose pads) are non-returnable once opened."},{"heading":"Intellectual Property","body":"All content on this website including text, images, logos, and design is the property of Power Eyes Opticals. You may not reproduce, copy or distribute any content without prior written permission."},{"heading":"Limitation of Liability","body":"Power Eyes Opticals is not liable for any indirect, incidental or consequential damages arising from the use of our products or website. Our liability is limited to the value of the order in question. This does not affect your statutory rights under the Consumer Protection Act 2019."},{"heading":"Governing Law","body":"These terms are governed by the laws of India. Any disputes arising from these terms or your use of our website shall be subject to the exclusive jurisdiction of courts in Chennai, Tamil Nadu."}]}$j$, 31),
  ('returns', 'Returns & Exchange', 'Simple, hassle-free returns', $j${"sections":[{"icon":"✅","heading":"Frames — 7 Day Return","items":["Unworn and undamaged frames only","Original bill and packaging required","Return to any Power Eyes store in person","Full refund to original payment method within 5–7 business days","Exchange for a different frame of equal or higher value (pay difference)"]},{"icon":"🔭","heading":"Prescription Lenses — Not Returnable","items":["Prescription lenses are custom-made for your eyes and cannot be returned","If lenses do not match the prescription you provided, we will remake them free within 30 days","If there is a manufacturing defect (coating peeling, incorrect power), we replace at no charge","Power correction: if you return for a power change within 30 days and your Rx was issued by us, lenses are remade free"]},{"icon":"🔵","heading":"Contact Lenses — No Return Once Opened","items":["Sealed, unopened boxes may be exchanged within 7 days","Once the box is opened, contact lenses cannot be returned for hygiene reasons","Defective lenses (torn, damaged inside sealed pack) will be replaced"]},{"icon":"📦","heading":"Online Orders — Return Process","items":["Log in to My Account → My Orders → select order → Request Return (coming soon)","Or WhatsApp us on 9840496404 with your order number","We will arrange courier pickup from your address for orders above ₹2,000","For smaller orders, you can return to either store directly","Refund processed within 5–7 business days after we receive and inspect the item"]}]}$j$, 32),
  ('faq', 'Frequently Asked Questions', 'Quick answers about eye tests, frames, lenses and orders', $j${"faq":[{"title":"Eye Testing","items":[{"q":"Is the eye test free?","a":"Yes. A comprehensive eye test at both our Mogappair stores is completely free, with no obligation to purchase. We use digital auto-refractors for accurate results."},{"q":"How long does an eye test take?","a":"A standard comprehensive eye test takes 20–30 minutes. Contact lens fittings and children's tests may take slightly longer."},{"q":"How often should I get my eyes tested?","a":"Adults with no known issues: every 2 years. Children: annually. If you wear glasses or contact lenses, or have a family history of eye disease, annually is recommended."},{"q":"Can I bring my existing prescription from another clinic?","a":"Yes. We accept valid prescriptions from any registered ophthalmologist or optometrist. The prescription must be less than 2 years old for glasses and 1 year old for contact lenses."},{"q":"Do you test children's eyes?","a":"Yes. We offer specialist children's eye tests (below 16 years) free of charge. We recommend first eye test at age 3–4, then annually through school years."}]},{"title":"Ordering & Delivery","items":[{"q":"How long does it take to get my glasses ready?","a":"Single vision glasses: 2–3 working days. Progressive / bifocal lenses: 5–7 working days. High-power prescriptions may take longer. You'll receive a WhatsApp message when ready."},{"q":"Do you offer home delivery?","a":"Yes. We deliver across Chennai and major Indian cities. Free shipping on orders above ₹999. Express delivery (1–2 days) is available for ₹99."},{"q":"Can I pick up from the store?","a":"Yes. Store pickup is always free. Choose 'Store Pickup' at checkout and select your preferred store (Mogappair East or Mogappair West). We'll WhatsApp you when your order is ready."},{"q":"Can I order glasses online with my prescription?","a":"Yes. Upload a photo of your prescription during checkout, or enter values manually. Our optometrist reviews every prescription before the order goes to the lab."}]},{"title":"Products & Lenses","items":[{"q":"Are all products genuine?","a":"Yes. 100% of products sold at Power Eyes Opticals are purchased from authorised distributors. We do not sell grey market, parallel import or counterfeit products."},{"q":"What lens index should I choose?","a":"Our lens recommendation engine selects the right index based on your prescription. As a guide: mild powers (up to ±2D) use 1.56 standard; moderate (±2–4D) use 1.60; high (±4–6D) use 1.67; very high (above ±6D) use 1.74."},{"q":"Do you offer progressive lenses?","a":"Yes. We offer single vision, progressive, bifocal and occupational lenses. Progressive lenses are available from ₹3,990 with anti-reflective coating included."},{"q":"Can I add blue light filtering to any lens?","a":"Yes. Blue light filter is available as an add-on for all lens packages. We recommend it for customers who spend 4+ hours daily on screens."},{"q":"Do you sell contact lenses?","a":"Yes. We stock daily, monthly, toric and coloured contact lenses from brands including Alcon, Johnson & Johnson and Bausch & Lomb. A contact lens fitting is required for first-time wearers."}]},{"title":"Returns & Warranty","items":[{"q":"What is your return policy?","a":"You can return or exchange unworn frames within 7 days of purchase with the original bill. Prescription lenses cannot be returned unless there is a manufacturing defect. If your prescription was wrong, we will remake the lenses free of charge within 30 days."},{"q":"What does the warranty cover?","a":"All frames come with a 1-year manufacturing warranty covering defects in material and workmanship — hinge failures, coating peeling and nose pad defects. It does not cover accidental damage, scratches from normal use or lost frames."},{"q":"What if my lenses are scratched?","a":"We offer free adjustments for life on all frames purchased from us. Scratched lenses can be replaced at a discount — bring your original frame and prescription to any store."}]},{"title":"Payments","items":[{"q":"What payment methods do you accept?","a":"Online: UPI (Google Pay, PhonePe, Paytm), Credit/Debit Card, Net Banking via Razorpay. In-store: Cash, UPI, card. We also accept partial advance payment for prescription lens orders."},{"q":"Is online payment secure?","a":"Yes. All online payments are processed through Razorpay, which is PCI-DSS Level 1 compliant. We never store your card details."}]}]}$j$, 33)
) as v(slug,title,subtitle,body,ord) on conflict (org_id, slug) do nothing;
update site_pages set body = body || $j${"callout":{"title":"7-Day Easy Returns on Frames","text":"Return unworn frames within 7 days for a full refund — no questions asked."},"extra":{"icon":"✗","heading":"What's NOT Covered","items":["Accidental damage, scratches, breakage after delivery","Frames with signs of wear or alteration","Items returned after 7 days (unless manufacturing defect)","Customised or engraved products","Prescription lenses (custom-made for your eyes)","Opened contact lens boxes"]}}$j$::jsonb where slug = 'returns' and org_id = p_org;

